from specflow.refmodel.temporal import after, throughout, worst


def decide(trace):
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items())
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    applies = _holds({"ena": 1, "nReset": 1, "rst": 0})
    closes = _any([{"cmd_ack": 1}, {"al": 1}])
    follows = True  # normalized activation.effect_follows

    windows = after(trace, applies, until=closes)

    def const_low(r):
        return r["outputs"].get("scl_o") == 0 and r["outputs"].get("sda_o") == 0

    return worst([throughout(w, const_low, after_activation=follows) for w in windows])

from specflow.refmodel.temporal import after, edges, eventually, worst

def decide(trace):
    def _holds(cond):
        def p(row):
            return all(
                row['outputs'].get(k, row['inputs'].get(k)) == v
                for k, v in cond.items())
        return p

    # activation.inputs: pins the window to an actual active (non-NOP)
    # command, out of reset, enabled -- the qualifier the prior answer
    # omitted, which let it open during idle/reset defaults.
    active = _holds({'cmd': 1, 'ena': 1, 'nReset': 1, 'rst': 0})

    # opens_on alt1, transcribed literally (din, not sda_oen).
    alt1 = _holds({'din': 1, 'scl_i': 1, 'sda_i': 0})

    # opens_on alt2: scl_i high at the edge filtered sda_i rises.
    rose_sda = set(edges(trace, 'sda_i', 'rise'))

    def alt2(row):
        return row['edge'] in rose_sda and row['inputs'].get('scl_i') == 1

    def opens(row):
        return active(row) and (alt1(row) or alt2(row))

    def closes(row):
        return row['outputs'].get('cmd_ack') == 1 or row['outputs'].get('al') == 1

    windows = after(trace, opens, until=closes)

    return worst([
        eventually(w, lambda r: r['outputs'].get('al') == 1,
                   after_activation=True, strong=True)
        for w in windows
    ])

from specflow.refmodel.temporal import after, never, stable, worst


def decide(trace):
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items())
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    windows = after(trace, _holds({"ena": 0}), until=_holds({"ena": 1}),
                     aborts=_any([{"nReset": 0}, {"rst": 1}]))

    verdicts = []
    for w in windows:
        verdicts.append(never(w, lambda r: r["outputs"]["cmd_ack"] == 1,
                               after_activation=True))
        verdicts.append(stable(w, "dout", after_activation=True))
        verdicts.append(stable(w, "busy", after_activation=True))
        verdicts.append(stable(w, "scl_oen", after_activation=True))
        verdicts.append(stable(w, "sda_oen", after_activation=True))
    return worst(verdicts)

from specflow.refmodel.temporal import after, eventually, worst, edges

def decide(trace):
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items())
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    rose = edges(trace, "sda_i", "rise")
    activation_inputs = _holds({"cmd": 1, "ena": 1, "nReset": 1, "rst": 0})

    def opens(row):
        return (row["edge"] in rose
                and row["inputs"].get("scl_i") == 1
                and activation_inputs(row))

    closes = _any([{"cmd_ack": 1}, {"al": 1}])
    aborts = _any([{"nReset": 0}, {"rst": 1}])

    windows = after(trace, opens, until=closes, aborts=aborts)

    return worst([
        eventually(w, lambda r: r["outputs"].get("al") == 1,
                   after_activation=True, strong=True)
        for w in windows
    ])

