from specflow.refmodel.temporal import after, throughout, worst


def decide(trace):
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items())
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    applies = _holds({"cmd": 4, "ena": 1})
    closes = _any([{"scl_oen": 0}, {"cmd_ack": 1}, {"al": 1}])
    follows = True  # normalized activation.effect_follows

    windows = after(trace, applies, until=closes)

    def released_or_concluding(r):
        # sda_oen must be released throughout the READ data-bit phase, but the
        # specification pins WHILE the slave can drive the bit, and never says
        # sda_oen must still read 1 on the exact row the phase concludes (SCL
        # pulled low to end the sample window, the command completing, or
        # arbitration being lost). `closes` can only be true at the window's
        # own last row -- that is what ends it -- so this excuses the
        # requirement there and only there, while still demanding release on
        # every row strictly inside the window.
        return r["outputs"].get("sda_oen") == 1 or closes(r)

    return worst([throughout(w, released_or_concluding, after_activation=follows)
                  for w in windows])

from specflow.refmodel.temporal import after, eventually, worst

def decide(trace):
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items())
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    activation = _holds({"cmd": 4, "din": 1, "ena": 1, "nReset": 1, "rst": 0})
    closes = _holds({"cmd_ack": 1})
    # Reset during a command voids the attempt rather than ending it --
    # 'Reset during a command releases both bus lines and suppresses
    # acknowledgement' -- so it belongs beside arbitration loss in aborts,
    # not left unguarded to run the window off the end of the trace.
    aborts = _any([{"al": 1}, {"nReset": 0}, {"rst": 1}])

    windows = after(trace, activation, until=closes, aborts=aborts)

    return worst([
        eventually(w, lambda r: r["outputs"].get("scl_oen") == 0,
                   after_activation=True, strong=True)
        for w in windows
    ])

from specflow.refmodel.temporal import after, edges, worst


def decide(trace):
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items())
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    opens = _holds({"cmd": 8, "ena": 1})
    closes = _any([{"cmd_ack": 1}, {"al": 1}])

    windows = after(trace, opens, until=closes)
    if not windows:
        return (None, None,
                'no READ command (cmd=8 while ena=1) was issued in this trace')

    # Proxy for the spec's 'filtered SCL rising edge' sampling instant:
    # the earliest point at which the raw bus input scl_i is observed to
    # rise while the DUT has itself released SCL (scl_oen=1) -- the first
    # hard, boundary-visible evidence that the READ's sampled high phase
    # has actually been reached, rather than a snapshot taken merely at
    # command acceptance.
    scl_rose = edges(trace, "scl_i", "rise")

    per_window = []
    for w in windows:
        rows = w.rows
        anchor_idx = None
        for i, r in enumerate(rows):
            if r["edge"] in scl_rose and r["outputs"].get("scl_oen") == 1:
                anchor_idx = i
                break

        if anchor_idx is None:
            per_window.append((None, w.edge,
                'no external SCL rise while the DUT had released SCL was '
                'observed during this READ command; the sampled high phase '
                'was never seen in this window'))
            continue

        expected = rows[anchor_idx]["inputs"].get("sda_i")
        anchor_edge = rows[anchor_idx]["edge"]
        found = any(r["outputs"].get("dout") == expected
                    for r in rows[anchor_idx:])

        if found:
            per_window.append((True, anchor_edge,
                f'dout reached the sampled SDA value ({expected}) after the '
                f'SCL-high sampling phase began at edge {anchor_edge}'))
        else:
            last_edge = rows[-1]["edge"] if rows else w.edge
            per_window.append((False, last_edge,
                f'dout never reflected the sampled SDA value ({expected}) '
                f'after the SCL-high sampling phase began at edge {anchor_edge}'))

    return worst(per_window)
